fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let max_len = std::cmp::max(m, n);

    let mut output_a = Vec::with_capacity(max_len);
    let mut output_b = Vec::with_capacity(max_len);

    if m == 1 {
        // If a has length 1, repeat its value to fill output_a
        let value_a = a[0];
        output_a.extend(std::iter::repeat(value_a).take(max_len));
    } else {
        // If a has length greater than 1, copy it unchanged
        output_a.extend(&a);
    }

    if n == 1 {
        // If b has length 1, repeat its value to fill output_b
        let value_b = b[0];
        output_b.extend(std::iter::repeat(value_b).take(max_len));
    } else {
        // If b has length greater than 1, copy it unchanged
        output_b.extend(&b);
    }

    // If the lengths are different, we need to truncate the longer output to max_len
    if output_a.len() > max_len {
        output_a.truncate(max_len);
    }
    if output_b.len() > max_len {
        output_b.truncate(max_len);
    }

    (output_a, output_b)
}